p.write_text(s,encoding='utf-8')
p=Path('scripts/experience.py'); s=p.read_text(encoding='utf-8').replace('Book an introductory briefing or use the contact form to prepare an email.', 'Request a demo or send us a question through the contact form.'); p.write_text(s,encoding='utf-8')
p=Path('README.md'); s=p.read_text(encoding='utf-8')
