s=s.replace('python -m http.server 4173 --bind 127.0.0.1 --directory public', 'python -m pip install -r requirements.txt\npython server.py')
s=s.replace('The form prepares an email draft and supports copying the request. It does not send mail or claim submission success.', 'The form posts to `/api/contact`. Live delivery requires the mail configuration described in `docs/CONTACT-DELIVERY.md`. It never reports success unless the configured mail service accepts the request.')
s=s.replace('`render.yaml` runs the Python builder and serves `public/`.', '`render.yaml` installs the Python dependencies, builds the pages, and serves `public/` through Gunicorn and Flask.')
